import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { AsOf } from './as-of';

// Who is signed in and which sheet is active. Everything else in the app is kept per sheet.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);
  private readonly asOf = inject(AsOf);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  // The active sheet's today (yyyy-mm-dd): every date decision and default date uses it.
  readonly sheetToday = signal<string | null>(null);
  // Whether the active sheet is archived: it stays visible and every change on it is refused.
  readonly sheetArchived = signal(false);
  // The number of the active sheet's last bulk settle batch, or null when there has been none.
  readonly sheetLastBatch = signal<number | null>(null);
  // Counts sheet loads, so a view re-reads the store even when the same id is loaded again.
  readonly loads = signal(0);
  // The date the screen shows the sheet as of, or null: while set, every figure is as the sheet stood at the end of
  // it, the date stands in for the sheet's today, and every change is refused.
  readonly sheetAsOf = this.asOf.date.asReadonly();

  async signIn(name: string): Promise<void> {
    const u = await firstValueFrom(this.http.post<{ name: string }>('/api/signin', { name }));
    this.user.set(u.name);
  }

  async loadSheet(id: string): Promise<void> {
    const s = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}`, null),
    );
    this.sheetId.set(s.id);
    this.sheetToday.set(s.today);
    this.sheetArchived.set(s.archived);
    this.sheetLastBatch.set(s.lastBatch);
    this.loads.update((n) => n + 1);
  }

  // Shows the sheet as of the date (null: as it stands now), re-read from the store.
  async setAsOf(date: string | null): Promise<void> {
    this.asOf.date.set(date);
    const id = this.sheetId();
    if (id) await this.loadSheet(id);
  }

  async setToday(today: string): Promise<void> {
    const id = this.sheetId();
    if (!id) return;
    const s = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }),
    );
    this.sheetToday.set(s.today);
  }

  // Clones the active sheet to another id, never used before.
  async cloneSheet(toSheetId: string): Promise<void> {
    const id = this.sheetId();
    if (!id) return;
    await firstValueFrom(this.http.post(`/api/sheets/${encodeURIComponent(id)}/clone`, { toSheetId }));
  }

  async archive(): Promise<void> {
    const id = this.sheetId();
    if (!id) return;
    const s = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null),
    );
    this.sheetArchived.set(s.archived);
  }
}

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
  lastBatch: number | null;
}
package net.officefloor.hq.app.session;

import jakarta.servlet.http.HttpSession;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/** Sign-in by name only; there is no password. The name is kept in the HTTP session as {@link #USER}. */
@RestController
public class SessionController {

    /** The session attribute holding the signed-in user's name. */
    public static final String USER = "user";

    public record SignIn(@NotBlank @Size(max = 100) String name) {
    }

    public record User(String name) {
    }

    @PostMapping("/api/signin")
    public User signIn(@Valid @RequestBody SignIn request, HttpSession session) {
        String name = request.name().trim();
        session.setAttribute(USER, name);
        return new User(name);
    }
}
import { Component, computed, input } from '@angular/core';
import { STATUSES } from '../summary/summary';

// The sheet's counters, shown at all times: each repeats a figure shown elsewhere — the status counts those of the
// summary, the two totals the sheet's totals, and the signed-in user's own figures those of their person's row.
@Component({
  selector: 'app-header',
  template: `
    <header aria-label="Sheet counters">
      <dl>
        <dt>People</dt>
        <dd data-testid="header-people-count">{{ peopleCount() }}</dd>
        @for (s of byStatus(); track s.status) {
          <dt>{{ s.status }}</dt>
          <dd [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count }}</dd>
        }
        <dt>Due</dt>
        <dd data-testid="header-due-total">{{ dueTotal() }}</dd>
        <dt>Overdue</dt>
        <dd data-testid="header-overdue-total">{{ overdueTotal() }}</dd>
        <dt>My due</dt>
        <dd data-testid="my-due-total">{{ myDueTotal() }}</dd>
        <dt>My overdue</dt>
        <dd data-testid="my-overdue-total">{{ myOverdueTotal() }}</dd>
      </dl>
    </header>
  `,
})
export class Header {
  // Everyone on the sheet, retired people included.
  readonly peopleCount = input(0);
  // The status of every claim on the sheet, as the summary counts them.
  readonly statuses = input<readonly string[]>([]);
  readonly dueTotal = input('');
  readonly overdueTotal = input('');
  // The signed-in user's own figures, as on the row of the person with their name or alias; blank with no such person.
  readonly myDueTotal = input('');
  readonly myOverdueTotal = input('');

  protected readonly byStatus = computed(() =>
    STATUSES.map((status) => ({ status, count: this.statuses().filter((s) => s === status).length })),
  );
}
import { Component, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { People } from '../people/people';
import { Rates } from '../rates/rates';
import { Settings, SettingsStore } from '../settings/settings';
import { Delegation } from '../delegation/delegation';
import { Holidays } from '../holidays/holidays';
import { VoidReasons } from '../void-reasons/void-reasons';
import { ClaimTemplates } from '../claim-templates/claim-templates';
import { Pools } from '../pools/pools';
import { AuditViewer } from '../audit-viewer/audit-viewer';
import { TreeSearch } from '../tree-search/tree-search';
import { PlanStore } from '../plans/plans';

// The one screen: sign in by name, then load a sheet by id.
@Component({
  selector: 'app-home',
  imports: [People, Rates, Settings, Delegation, Holidays, VoidReasons, ClaimTemplates, Pools, TreeSearch, AuditViewer],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>

      <form (submit)="load($event)" aria-label="Load sheet">
        <label for="sheet-id">Sheet id</label>
        <input
          id="sheet-id"
          data-testid="sheet-id-input"
          [value]="sheetInput()"
          (input)="sheetInput.set(value($event)); sheetError.set(null)"
        />
        <button type="submit" data-testid="sheet-load">Load</button>
        @if (sheetError(); as err) {
          <p role="alert" data-testid="sheet-load-error">{{ err }}</p>
        }
      </form>

      @if (session.sheetId(); as id) {
        <p>Sheet: <strong data-testid="sheet-current-id">{{ id }}</strong></p>
        <p>Today: <strong data-testid="sheet-today">{{ session.sheetToday() }}</strong></p>
        <p>Archived: <strong data-testid="sheet-archived">{{ session.sheetArchived() ? 'yes' : 'no' }}</strong></p>
        <p>Parent sheet: <strong data-testid="sheet-parent">{{ settings.parent() ?? '' }}</strong></p>

        <form (submit)="saveToday($event)" aria-label="Change today">
          <label for="sheet-today">New today</label>
          <input
            id="sheet-today"
            type="date"
            data-testid="sheet-today-input"
            [value]="todayInput()"
            (input)="todayInput.set(value($event)); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-today-save">Set today</button>
        </form>
        <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>

        <form (submit)="cloneSheet($event)" aria-label="Clone sheet">
          <label for="sheet-clone-to">Clone to sheet id</label>
          <input
            id="sheet-clone-to"
            data-testid="sheet-clone-to"
            [value]="cloneInput()"
            (input)="cloneInput.set(value($event)); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-clone">Clone sheet</button>
        </form>
        <p>Cloned to: <strong data-testid="sheet-cloned-to">{{ clonedTo() ?? '' }}</strong></p>

        <p>As of: <strong data-testid="sheet-asof">{{ session.sheetAsOf() ?? '' }}</strong></p>
        <form (submit)="setAsOf($event)" aria-label="Show the sheet as of a date">
          <label for="asof-date">Show as of</label>
          <input
            id="asof-date"
            type="date"
            data-testid="asof-date"
            [value]="asOfInput()"
            (input)="asOfInput.set(value($event)); asOfError.set(null)"
          />
          <button type="submit" data-testid="asof-set">Set as of</button>
          <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
          @if (asOfError(); as err) {
            <p role="alert" data-testid="asof-error">{{ err }}</p>
          }
        </form>
        @if (todayError(); as err) {
          <p role="alert" data-testid="sheet-error">{{ err }}</p>
        }

        <app-rates />
        <app-settings />
        <app-delegation />
        <app-holidays />
        <app-void-reasons />
        <app-claim-templates />
        <app-people />
        <app-pools />
        <app-tree-search />
        <app-audit-viewer />
      }
    } @else {
      <form (submit)="signIn($event)" aria-label="Sign in">
        <label for="signin-name">Your name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set(value($event)); signinError.set(null)"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signinError(); as err) {
          <p role="alert" data-testid="signin-error">{{ err }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly settings = inject(SettingsStore);
  private readonly plans = inject(PlanStore);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly signinError = signal<string | null>(null);
  protected readonly sheetError = signal<string | null>(null);
  protected readonly todayInput = signal('');
  protected readonly cloneInput = signal('');
  // The id the sheet was last cloned to; cleared while a clone runs.
  protected readonly clonedTo = signal<string | null>(null);
  // The sheet's own error: a refused today change, archive or clone.
  protected readonly todayError = signal<string | null>(null);

  protected readonly asOfInput = signal('');
  // The as-of entry's own error: a date that is not one, or a sheet that could not be shown as of it.
  protected readonly asOfError = signal<string | null>(null);

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async signIn(e: Event): Promise<void> {
    e.preventDefault();
    this.signinError.set(null);
    const name = this.nameInput().trim();
    if (!name) {
      this.signinError.set('Enter a name.');
      return;
    }
    try {
      await this.session.signIn(name);
    } catch {
      this.signinError.set('Could not sign in.');
    }
  }

  protected async load(e: Event): Promise<void> {
    e.preventDefault();
    this.sheetError.set(null);
    const id = this.sheetInput().trim();
    if (!id) {
      this.sheetError.set('Enter a sheet id.');
      return;
    }
    try {
      await this.session.loadSheet(id);
    } catch {
      this.sheetError.set('Could not load that sheet.');
    }
  }

  protected async saveToday(e: Event): Promise<void> {
    e.preventDefault();
    this.todayError.set(null);
    const today = this.todayInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.todayError.set('Enter a date as yyyy-mm-dd.');
      return;
    }
    try {
      await this.session.setToday(today);
    } catch {
      this.todayError.set('Could not change the date.');
      return;
    }
    // the plans' next dates follow the sheet's today
    const sheet = this.session.sheetId();
    if (sheet) await this.plans.load(sheet).catch(() => undefined);
  }

  protected async setAsOf(e: Event): Promise<void> {
    e.preventDefault();
    this.asOfError.set(null);
    const date = this.asOfInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.asOfError.set('Enter a date as yyyy-mm-dd.');
      return;
    }
    try {
      await this.session.setAsOf(date);
    } catch {
      this.asOfError.set('Could not show the sheet as of that date.');
    }
  }

  protected async clearAsOf(): Promise<void> {
    this.asOfError.set(null);
    try {
      await this.session.setAsOf(null);
    } catch {
      this.asOfError.set('Could not show the sheet as it stands.');
    }
  }

  protected async cloneSheet(e: Event): Promise<void> {
    e.preventDefault();
    this.todayError.set(null);
    this.clonedTo.set(null);
    const to = this.cloneInput().trim();
    if (!to) {
      this.todayError.set('Enter the id of the sheet to clone to.');
      return;
    }
    try {
      await this.session.cloneSheet(to);
      this.clonedTo.set(to);
    } catch {
      this.todayError.set('Could not clone the sheet to that id.');
    }
  }

  protected async archive(): Promise<void> {
    this.todayError.set(null);
    try {
      await this.session.archive();
    } catch {
      this.todayError.set('Could not archive the sheet.');
    }
  }
}
